catalogo.mrc: os registros em MARC 21 com os exemplares no campo 952. Carrega-se em «Ferramentas > Preparar registros MARC para importação», e ao importar você indica para adicionar os exemplares.

lectores.csv: os leitores, na «Importação de usuários» do Koha, com sua carteirinha. Antes é preciso criar no Koha a biblioteca (o código da coluna branchcode, também em $a e $b de cada 952) e as categorias ST, T, S e PT; e os tipos de exemplar BK e REF.

prestamos.koc: os livros que estão fora, em «Circulação > Carregar arquivo de circulação offline». Vai no final, com os leitores e os exemplares já dentro.';
$string['copymade'] = 'Cópia feita.';
$string['copymake'] = 'Fazer uma cópia agora';
$string['copyreadme'] = 'Cópia das bibliotecas de {$a->entity}, feita em {$a->date} por Oksigenia Ayvurenda {$a->release}.

Cada arquivo CSV é uma tabela, com os nomes das colunas na primeira linha. Abrem-se em qualquer planilha.

- entity, library: a entidade e suas bibliotecas.
- record, authority, recauth: o catálogo (títulos, autores, assuntos…).
- item: os exemplares e o material, com seus códigos.
- reader, member: os leitores e sua turma em cada ano letivo.
- loan: os empréstimos, em andamento e devolvidos.
- hold: as reservas, na fila, separadas e concluídas.
- stocktake, stockread: os inventários e o que foi lido em cada um.
- withdrawal, withdrawn: as atas de descarte e seus exemplares.
- lot, lotitem: os lotes entre bibliotecas e seus exemplares.
- digital: os formatos digitais dos registros (sem seus arquivos, que ficam no local).
- rule, year, tutor, source: regras de empréstimo, anos letivos, tutores e de onde veio cada linha.
- catalogo.mrc e catalogo.xml: o catálogo em MARC21 (ISO 2709 e MARCXML), com seus exemplares no campo 852, para levá-lo a qualquer programa de biblioteca.
- catalogo-dc.xml: o catálogo em Dublin Core, para repositórios e catálogos que não leem MARC.
- catalogo.ris: o catálogo em RIS, para gerenciadores de referências como Zotero ou Mendeley.
- challenge, wish: os desafios das turmas e o que pediram.
- review, roomread: as resenhas e o que foi lido na sala.
- bankset, banktitle: os lotes do banco de livros didáticos e seus títulos.
- koha/: o mesmo, preparado para levar ao Koha (veja o LEIAME).

As capas e o acervo digital vão em outra cópia, a dos arquivos. As vozes gravadas não saem do servidor.

Linhas de cada arquivo:
{$a->counts}
